SourceCode.Declaration:
/// <summary>
/// Server side of the D365 Data Quiz: generates multiple choice questions from live data, checks the answers and scores them.
/// </summary>
/// <remarks>
/// Every public method named q... is a question generator. It returns a question, or null when the environment has no
/// data for it, so the quiz adapts to the data of each environment. The browser never receives the correct answer
/// before it has answered, and every value it sends is validated here.
/// </remarks>
public class DEVTutorialArcadeQuizEngine
{
    public const int Seconds = 20;
    public const int MaxQuestions = 20;
    public const int MinMonthRecords = 5;

    Array   questions;
    int     total;
    int     current;
    int     score;
    int     streak;
    int     correctCount;
    boolean fiftyUsed;
    str     quizId;

    // months used by the month based questions (the latest month with enough records), read once per quiz
    date    invoiceMonthCache;
    date    paymentMonthCache;
    date    orderMonthCache;

    // wrong-answer candidates, read once per quiz and shared by the generators
    container customerNameCache;
    container vendorNameCache;
    container itemNameCache;
    container workerNameCache;
}

Method.Source:
public static DEVTutorialArcadeQuizEngine construct()
{
    return new DEVTutorialArcadeQuizEngine();
}

/// <summary>
/// Gets the score calculated by the server.
/// </summary>
public int parmScore()
{
    return score;
}

/// <summary>
/// Starts a quiz.
/// </summary>
/// <param name = "_count">Requested number of questions.</param>
/// <returns>JSON: quizId, total and the first question.</returns>
public str start(int _count)
{
    int                           questionCount = max(3, min(DEVTutorialArcadeQuizEngine::MaxQuestions, _count));
    Array                         pool          = this.buildPool(questionCount);
    DEVTutorialArcadeQuizQuestion question;
    int                           i;

    total = min(questionCount, pool.lastIndex());
    if (!total)
    {
        return DEVTutorialArcadeQuizEngine::errorJson("No data was found for the quiz in this environment.");
    }

    questions = new Array(Types::Class);
    for (i = 1; i <= total; i++)
    {
        question = pool.value(i);
        question.parmQuestionNum(i);
        question.parmQuestionId(strFmt('Q%1', i));
        questions.value(i, question);
    }

    quizId       = guid2Str(newGuid());
    current      = 1;
    score        = 0;
    streak       = 0;
    correctCount = 0;
    fiftyUsed    = false;

    return DEVTutorialArcadeJson::object([
        DEVTutorialArcadeJson::pair('quizId', DEVTutorialArcadeJson::quote(quizId)),
        DEVTutorialArcadeJson::pair('total', int2Str(total)),
        DEVTutorialArcadeJson::pair('question', this.currentQuestion().toJson(total))]);
}

/// <summary>
/// Checks the answer to the current question and scores it.
/// </summary>
/// <param name = "_questionId">Id of the question the browser answered.</param>
/// <param name = "_answer">0-based option, -1 when the time ran out.</param>
/// <param name = "_ms">Milliseconds the player needed.</param>
/// <returns>JSON: correct, correctIndex, points, score, streak, explanation, query, last.</returns>
public str answer(str _questionId, int _answer, int _ms)
{
    DEVTutorialArcadeQuizQuestion question = this.currentQuestion();
    int     answer = _answer >= 0 && _answer <= 3 ? _answer : -1;
    int     ms     = max(0, min(DEVTutorialArcadeQuizEngine::Seconds * 1000, _ms));
    boolean isCorrect;
    int     points;
    real    remaining, multiplier;

    if (!question || question.parmQuestionId() != _questionId || question.parmAnswered())
    {
        return DEVTutorialArcadeQuizEngine::errorJson("Unknown or already answered question.");
    }

    isCorrect = answer == question.parmCorrectIndex();
    if (isCorrect)
    {
        streak++;
        correctCount++;
        remaining  = DEVTutorialArcadeQuizEngine::Seconds - ms / 1000;
        multiplier = streak >= 5 ? 2.0 : (streak >= 3 ? 1.5 : 1.0);
        points     = real2int(round((100 + remaining * 5) * multiplier * (question.parmFiftyUsed() ? 0.5 : 1.0), 1));
        score     += points;
    }
    else
    {
        streak = 0;
    }

    question.parmAnswered(true);
    question.parmAnswer(answer);
    question.parmPoints(points);

    return DEVTutorialArcadeJson::object([
        DEVTutorialArcadeJson::pair('correct', DEVTutorialArcadeJson::bool(isCorrect)),
        DEVTutorialArcadeJson::pair('correctIndex', int2Str(question.parmCorrectIndex())),
        DEVTutorialArcadeJson::pair('points', int2Str(points)),
        DEVTutorialArcadeJson::pair('score', int2Str(score)),
        DEVTutorialArcadeJson::pair('streak', int2Str(streak)),
        DEVTutorialArcadeJson::pair('explanation', DEVTutorialArcadeJson::quote(question.parmExplanation())),
        DEVTutorialArcadeJson::pair('query', DEVTutorialArcadeJson::quote(question.parmXppQuery())),
        DEVTutorialArcadeJson::pair('last', DEVTutorialArcadeJson::bool(current >= total))]);
}

/// <summary>
/// Moves to the next question.
/// </summary>
/// <returns>JSON: the next question, or done = true.</returns>
public str nextQuestion()
{
    DEVTutorialArcadeQuizQuestion question = this.currentQuestion();

    if (!question || !question.parmAnswered())
    {
        return DEVTutorialArcadeQuizEngine::errorJson("Answer the current question first.");
    }

    current++;
    if (current > total)
    {
        return DEVTutorialArcadeJson::object([DEVTutorialArcadeJson::pair('done', 'true')]);
    }

    return DEVTutorialArcadeJson::object([DEVTutorialArcadeJson::pair('question', this.currentQuestion().toJson(total))]);
}

/// <summary>
/// The 50:50 joker (once per quiz): removes two wrong options.
/// </summary>
/// <param name = "_questionId">Id of the current question.</param>
/// <returns>JSON: remove = two 0-based option indexes.</returns>
public str fiftyFifty(str _questionId)
{
    DEVTutorialArcadeQuizQuestion question = this.currentQuestion();
    container wrong;
    int       i;

    if (fiftyUsed || !question || question.parmQuestionId() != _questionId || question.parmAnswered())
    {
        return DEVTutorialArcadeQuizEngine::errorJson("The 50:50 joker is not available.");
    }

    fiftyUsed = true;
    question.parmFiftyUsed(true);
    for (i = 0; i <= 3; i++)
    {
        if (i != question.parmCorrectIndex())
        {
            wrong += i;
        }
    }
    wrong = DEVTutorialArcadeQuizEngine::shuffle(wrong);

    return DEVTutorialArcadeJson::object([
        DEVTutorialArcadeJson::pair('remove', DEVTutorialArcadeJson::array([int2Str(conPeek(wrong, 1)), int2Str(conPeek(wrong, 2))]))]);
}

/// <summary>
/// Returns the result of the quiz.
/// </summary>
/// <returns>JSON: score, correct, total, title and a review of every question.</returns>
public str finish()
{
    DEVTutorialArcadeQuizQuestion question;
    container review;
    int       i;
    int       pct = total ? correctCount * 100 div total : 0;

    for (i = 1; i <= total; i++)
    {
        question = questions.value(i);
        review += DEVTutorialArcadeJson::object([
            DEVTutorialArcadeJson::pair('text', DEVTutorialArcadeJson::quote(question.parmText())),
            DEVTutorialArcadeJson::pair('correct', DEVTutorialArcadeJson::bool(question.parmAnswer() == question.parmCorrectIndex())),
            DEVTutorialArcadeJson::pair('answer', DEVTutorialArcadeJson::quote(question.parmAnswer() >= 0 ? question.choiceText(question.parmAnswer()) : '(no answer)')),
            DEVTutorialArcadeJson::pair('right', DEVTutorialArcadeJson::quote(question.choiceText(question.parmCorrectIndex()))),
            DEVTutorialArcadeJson::pair('points', int2Str(question.parmPoints()))]);
    }

    return DEVTutorialArcadeJson::object([
        DEVTutorialArcadeJson::pair('score', int2Str(score)),
        DEVTutorialArcadeJson::pair('correct', int2Str(correctCount)),
        DEVTutorialArcadeJson::pair('total', int2Str(total)),
        DEVTutorialArcadeJson::pair('title', DEVTutorialArcadeJson::quote(DEVTutorialArcadeQuizEngine::title(pct))),
        DEVTutorialArcadeJson::pair('review', DEVTutorialArcadeJson::array(review))]);
}

private DEVTutorialArcadeQuizQuestion currentQuestion()
{
    DEVTutorialArcadeQuizQuestion question;

    if (questions && current >= 1 && current <= total)
    {
        question = questions.value(current);
    }

    return question;
}

/// <summary>
/// Runs the question generators in random order until enough questions with data are found.
/// </summary>
/// <param name = "_wanted">Number of questions needed.</param>
private Array buildPool(int _wanted)
{
    container generators = DEVTutorialArcadeQuizEngine::shuffle([
        methodStr(DEVTutorialArcadeQuizEngine, qCompanyCount),
        methodStr(DEVTutorialArcadeQuizEngine, qAccountingCurrency),
        methodStr(DEVTutorialArcadeQuizEngine, qCompanyMostCustomers),
        methodStr(DEVTutorialArcadeQuizEngine, qWarehouseCount),
        methodStr(DEVTutorialArcadeQuizEngine, qLastCustomer),
        methodStr(DEVTutorialArcadeQuizEngine, qCustomerCount),
        methodStr(DEVTutorialArcadeQuizEngine, qCustGroupMost),
        methodStr(DEVTutorialArcadeQuizEngine, qCustHighestCredit),
        methodStr(DEVTutorialArcadeQuizEngine, qLastVendor),
        methodStr(DEVTutorialArcadeQuizEngine, qVendorCount),
        methodStr(DEVTutorialArcadeQuizEngine, qVendGroupMost),
        methodStr(DEVTutorialArcadeQuizEngine, qItemCount),
        methodStr(DEVTutorialArcadeQuizEngine, qItemHighestPrice),
        methodStr(DEVTutorialArcadeQuizEngine, qItemGroupCount),
        methodStr(DEVTutorialArcadeQuizEngine, qSalesOrdersInMonth),
        methodStr(DEVTutorialArcadeQuizEngine, qLastOrderLines),
        methodStr(DEVTutorialArcadeQuizEngine, qInvoiceCountMonth),
        methodStr(DEVTutorialArcadeQuizEngine, qInvoiceTotalMonth),
        methodStr(DEVTutorialArcadeQuizEngine, qLargestInvoiceMonth),
        methodStr(DEVTutorialArcadeQuizEngine, qTopInvoiceCustomerMonth),
        methodStr(DEVTutorialArcadeQuizEngine, qTopItemMonth),
        methodStr(DEVTutorialArcadeQuizEngine, qOpenPurchOrders),
        methodStr(DEVTutorialArcadeQuizEngine, qTopVendorPurchOrders),
        methodStr(DEVTutorialArcadeQuizEngine, qCustPaymentsMonth),
        methodStr(DEVTutorialArcadeQuizEngine, qTopPayingCustomer),
        methodStr(DEVTutorialArcadeQuizEngine, qLastVendPayment),
        methodStr(DEVTutorialArcadeQuizEngine, qWorkerCount),
        methodStr(DEVTutorialArcadeQuizEngine, qLastHired),
        methodStr(DEVTutorialArcadeQuizEngine, qEnabledUsers),
        methodStr(DEVTutorialArcadeQuizEngine, qNewestUser),
        methodStr(DEVTutorialArcadeQuizEngine, qBatchJobsActive),
        methodStr(DEVTutorialArcadeQuizEngine, qMainAccountCount),
        methodStr(DEVTutorialArcadeQuizEngine, qCurrencyCount)]);
    DictClass                     dictClass = new DictClass(classNum(DEVTutorialArcadeQuizEngine));
    Array                         pool      = new Array(Types::Class);
    DEVTutorialArcadeQuizQuestion question;
    int                           i, n;

    for (i = 1; i <= conLen(generators) && n < _wanted; i++)
    {
        try
        {
            question = dictClass.callObject(conPeek(generators, i), this);
            if (question)
            {
                n++;
                pool.value(n, question);
            }
        }
        catch
        {
            // a question whose data is missing or not accessible is simply skipped
        }
    }

    return pool;
}

/// <summary>
/// Creates a question with a numeric answer and three plausible wrong numbers.
/// </summary>
private DEVTutorialArcadeQuizQuestion numberQuestion(str _category, str _text, real _value, str _explanation, str _xppQuery)
{
    container factors = [0.55, 0.7, 0.8, 1.25, 1.4, 1.65, 1.9];
    str       correctText = DEVTutorialArcadeQuizEngine::formatNumber(_value);
    container wrong;
    real      candidate;
    str       candidateText;
    int       guard;

    while (conLen(wrong) < 3 && guard < 200)
    {
        guard++;
        if (abs(_value) < 12)
        {
            candidate = _value + DEVTutorialArcadeQuizEngine::random(9) - 5;
        }
        else
        {
            // not rounded to tens: the right answer must not be the only "unround" number
            candidate = _value * conPeek(factors, DEVTutorialArcadeQuizEngine::random(conLen(factors)));
            candidate = round(candidate, 1.0);
        }
        candidateText = DEVTutorialArcadeQuizEngine::formatNumber(candidate);
        if (candidate >= 0 && candidateText != correctText && !conFind(wrong, candidateText))
        {
            wrong += candidateText;
        }
    }

    return DEVTutorialArcadeQuizQuestion::construct(_category, _text, correctText, wrong, _explanation, _xppQuery);
}

/// <summary>
/// Creates a question whose wrong answers are picked from other values of the same kind.
/// </summary>
/// <returns>The question; null when there are fewer than three other values.</returns>
private DEVTutorialArcadeQuizQuestion choiceQuestion(str _category, str _text, str _correct, container _candidates, str _explanation, str _xppQuery)
{
    container pool = DEVTutorialArcadeQuizEngine::shuffle(_candidates);
    container wrong;
    str       option;
    int       i;

    for (i = 1; i <= conLen(pool) && conLen(wrong) < 3; i++)
    {
        option = conPeek(pool, i);
        if (option && option != _correct && !conFind(wrong, option))
        {
            wrong += option;
        }
    }

    if (conLen(wrong) < 3)
    {
        return null;
    }

    return DEVTutorialArcadeQuizQuestion::construct(_category, _text, _correct, wrong, _explanation, _xppQuery);
}

public DEVTutorialArcadeQuizQuestion qCompanyCount()
{
    CompanyInfo companyInfo;
    int         n;

    select count(RecId) from companyInfo;
    n = int642int(companyInfo.RecId);
    if (!n)
    {
        return null;
    }

    return this.numberQuestion('ORGANIZATION', "How many legal entities (companies) are set up in this environment?", n,
        strFmt("CompanyInfo holds %1 legal entities.", n),
        'select count(RecId) from companyInfo;');
}

public DEVTutorialArcadeQuizQuestion qAccountingCurrency()
{
    CurrencyCode currencyCode = Ledger::accountingCurrency(CompanyInfo::current());

    if (!currencyCode)
    {
        return null;
    }

    return this.choiceQuestion('ORGANIZATION', strFmt("What is the accounting currency of company %1?", curExt()), currencyCode,
        ['USD', 'EUR', 'GBP', 'CAD', 'JPY', 'CHF', 'AUD', 'DKK', 'CNY', 'SEK'],
        strFmt("The ledger of %1 uses %2 as its accounting currency.", curExt(), currencyCode),
        'Ledger::accountingCurrency(CompanyInfo::current())');
}

public DEVTutorialArcadeQuizQuestion qCompanyMostCustomers()
{
    CustTable  custTable;
    DataArea   dataArea;
    DataAreaId bestCompany;
    int64      bestCount;
    int64      runnerUp;
    container  companies;

    while select crosscompany count(RecId) from custTable
        group by DataAreaId
    {
        if (custTable.RecId > bestCount)
        {
            runnerUp = bestCount;
            bestCount   = custTable.RecId;
            bestCompany = strUpr(custTable.DataAreaId);   // DataAreaId is lower case; DataArea.id is not
        }
        else if (custTable.RecId > runnerUp)
        {
            runnerUp = custTable.RecId;
        }
    }
    if (!bestCompany || bestCount == runnerUp)
    {
        return null;
    }

    while select id from dataArea
        where dataArea.isVirtual == NoYes::No
    {
        companies += strUpr(dataArea.id);
    }

    return this.choiceQuestion('ORGANIZATION', "Which company has the most customers?", bestCompany, companies,
        strFmt("%1 has %2 customers, more than any other company.", bestCompany, bestCount),
        'select crosscompany count(RecId) from custTable group by DataAreaId;');
}

