    return this.numberQuestion('ORGANIZATION', strFmt("How many warehouses does %1 have?", curExt()), n,
        strFmt("InventLocation in %1 contains %2 warehouses.", curExt(), n),
        'select count(RecId) from inventLocation;');
}

public DEVTutorialArcadeQuizQuestion qLastCustomer()
{
    CustTable custTable;

    select firstonly custTable
        order by RecId desc;
    if (!custTable.RecId)
    {
        return null;
    }

    return this.choiceQuestion('CUSTOMERS', strFmt("Which customer was created most recently in %1?", curExt()),
        this.custText(custTable.AccountNum), this.customerNames(),
        strFmt("The newest CustTable record is %1, created on %2.", this.custText(custTable.AccountNum), DateTimeUtil::date(custTable.CreatedDateTime)),
        'select firstonly custTable order by RecId desc;');
}

