    }

    return this.numberQuestion('CUSTOMERS', strFmt("How many customers are there in %1?", curExt()), n,
        strFmt("CustTable in %1 has %2 records.", curExt(), n),
        'select count(RecId) from custTable;');
}

public DEVTutorialArcadeQuizQuestion qCustGroupMost()
{
    CustTable   custTable;
    CustGroup   custGroup;
    CustGroupId bestGroup;
    int64       bestCount;
    int64       runnerUp;
    container   groups;

    while select count(RecId) from custTable
        group by CustGroup
    {
        if (custTable.RecId > bestCount)
        {
            runnerUp = bestCount;
            bestCount = custTable.RecId;
            bestGroup = custTable.CustGroup;
        }
        else if (custTable.RecId > runnerUp)
        {
            runnerUp = custTable.RecId;
        }
    }
    if (!bestGroup || bestCount == runnerUp)
    {
        return null;
    }

    while select custGroup
    {
        groups += this.groupText(custGroup.CustGroup, custGroup.Name);
    }

    return this.choiceQuestion('CUSTOMERS', strFmt("Which customer group has the most customers in %1?", curExt()),
        this.groupText(bestGroup, CustGroup::find(bestGroup).Name), groups,
        strFmt("Customer group %1 contains %2 customers.", bestGroup, bestCount),
        'select count(RecId) from custTable group by CustGroup;');
}

public DEVTutorialArcadeQuizQuestion qCustHighestCredit()
{
    CustTable custTable, secondCust;

    select firstonly custTable
        order by CreditMax desc
        where custTable.CreditMax > 0;
    if (!custTable.RecId)
    {
        return null;
    }
    select firstonly CreditMax from secondCust
        order by CreditMax desc
        where secondCust.RecId != custTable.RecId;
    if (secondCust.CreditMax == custTable.CreditMax)
    {
        return null;   // no unique winner
    }

    return this.choiceQuestion('CUSTOMERS', strFmt("Which customer has the highest credit limit in %1?", curExt()),
        this.custText(custTable.AccountNum), this.customerNames(),
        strFmt("%1 has a credit limit of %2.", this.custText(custTable.AccountNum), DEVTutorialArcadeQuizEngine::formatNumber(custTable.CreditMax)),
        'select firstonly custTable order by CreditMax desc;');
}

