public DEVTutorialArcadeQuizQuestion qVendGroupMost()
{
    VendTable   vendTable;
    VendGroup   vendGroup;
    VendGroupId bestGroup;
    int64       bestCount;
    int64       runnerUp;
    container   groups;

    while select count(RecId) from vendTable
        group by VendGroup
    {
        if (vendTable.RecId > bestCount)
        {
            runnerUp = bestCount;
            bestCount = vendTable.RecId;
            bestGroup = vendTable.VendGroup;
        }
        else if (vendTable.RecId > runnerUp)
        {
            runnerUp = vendTable.RecId;
        }
    }
    if (!bestGroup || bestCount == runnerUp)
    {
        return null;
    }

    while select vendGroup
    {
        groups += this.groupText(vendGroup.VendGroup, vendGroup.Name);
    }

    return this.choiceQuestion('VENDORS', strFmt("Which vendor group is the largest in %1?", curExt()),
        this.groupText(bestGroup, VendGroup::find(bestGroup).Name), groups,
        strFmt("Vendor group %1 contains %2 vendors.", bestGroup, bestCount),
        'select count(RecId) from vendTable group by VendGroup;');
}

public DEVTutorialArcadeQuizQuestion qItemCount()
{
    InventTable inventTable;
