public DEVTutorialArcadeQuizQuestion qItemHighestPrice()
{
    InventTableModule inventTableModule, secondPrice;

    select firstonly inventTableModule
        order by Price desc
        where inventTableModule.ModuleType == ModuleInventPurchSales::Sales
           && inventTableModule.Price      > 0;
    if (!inventTableModule.RecId)
    {
        return null;
    }
    select firstonly Price from secondPrice
        order by Price desc
        where secondPrice.ModuleType == ModuleInventPurchSales::Sales
           && secondPrice.RecId      != inventTableModule.RecId;
    if (secondPrice.Price == inventTableModule.Price)
    {
        return null;   // no unique winner
    }

    return this.choiceQuestion('PRODUCTS', strFmt("Which released product has the highest sales price in %1?", curExt()),
        this.itemText(inventTableModule.ItemId), this.itemNames(),
        strFmt("%1 has a sales price of %2.", this.itemText(inventTableModule.ItemId), DEVTutorialArcadeQuizEngine::formatNumber(inventTableModule.Price)),
        'select firstonly inventTableModule order by Price desc where inventTableModule.ModuleType == ModuleInventPurchSales::Sales;');
}

