public DEVTutorialArcadeQuizQuestion qSalesOrdersInMonth()
{
    SalesTable  salesTable;
    date        lastDate;
    utcdatetime fromDateTime, toDateTime;
    int         n;

    lastDate = this.lastOrderMonth();
    if (lastDate == dateNull())
    {
        return null;
    }
    fromDateTime = DateTimeUtil::newDateTime(dateStartMth(lastDate), 0);
    toDateTime   = DateTimeUtil::newDateTime(endMth(lastDate), 86399);

    select count(RecId) from salesTable
        where salesTable.CreatedDateTime >= fromDateTime
           && salesTable.CreatedDateTime <= toDateTime;
    n = int642int(salesTable.RecId);

    return this.numberQuestion('SALES', strFmt("How many sales orders were created in %1?", this.monthText(lastDate)), n,
        strFmt("%1 sales orders were created in %2.", n, this.monthText(lastDate)),
        'select count(RecId) from salesTable where salesTable.CreatedDateTime >= monthStart && salesTable.CreatedDateTime <= monthEnd;');
}

public DEVTutorialArcadeQuizQuestion qLastOrderLines()
{
    SalesTable salesTable;
    SalesLine  salesLine;
    int        n;

    select firstonly salesTable
        order by RecId desc;
    if (!salesTable.RecId)
    {
        return null;
    }

    select count(RecId) from salesLine
        where salesLine.SalesId == salesTable.SalesId;
    n = int642int(salesLine.RecId);

    return this.numberQuestion('SALES', strFmt("How many lines does the latest sales order %1 have?", salesTable.SalesId), n,
        strFmt("Sales order %1 of customer %2 has %3 lines.", salesTable.SalesId, salesTable.CustAccount, n),
        'select count(RecId) from salesLine where salesLine.SalesId == salesTable.SalesId;');
}

public DEVTutorialArcadeQuizQuestion qInvoiceCountMonth()
{
    CustInvoiceJour custInvoiceJour;
    date            lastDate = this.lastInvoiceDate();
    int             n;

    if (lastDate == dateNull())
    {
        return null;
    }

    select count(RecId) from custInvoiceJour
        where custInvoiceJour.InvoiceDate >= dateStartMth(lastDate)
           && custInvoiceJour.InvoiceDate <= endMth(lastDate);
    n = int642int(custInvoiceJour.RecId);

    return this.numberQuestion('SALES', strFmt("How many sales invoices were posted in %1?", this.monthText(lastDate)), n,
        strFmt("CustInvoiceJour has %1 invoices dated %2.", n, this.monthText(lastDate)),
        'select count(RecId) from custInvoiceJour where custInvoiceJour.InvoiceDate >= monthStart && custInvoiceJour.InvoiceDate <= monthEnd;');
}

public DEVTutorialArcadeQuizQuestion qInvoiceTotalMonth()
