        strFmt("The invoices of %1 add up to %2 %3.", this.monthText(lastDate), DEVTutorialArcadeQuizEngine::formatNumber(custInvoiceJour.InvoiceAmountMST), Ledger::accountingCurrency()),
        'select sum(InvoiceAmountMST) from custInvoiceJour where custInvoiceJour.InvoiceDate >= monthStart && custInvoiceJour.InvoiceDate <= monthEnd;');
}

