public DEVTutorialArcadeQuizQuestion qTopInvoiceCustomerMonth()
{
    CustInvoiceJour custInvoiceJour;
    date            lastDate = this.lastInvoiceDate();
    CustInvoiceAccount bestAccount;
    int64           bestCount;
    int64           runnerUp;

    if (lastDate == dateNull())
    {
        return null;
    }

    while select count(RecId) from custInvoiceJour
        group by InvoiceAccount
        where custInvoiceJour.InvoiceDate >= dateStartMth(lastDate)
           && custInvoiceJour.InvoiceDate <= endMth(lastDate)
    {
        if (custInvoiceJour.RecId > bestCount)
        {
            runnerUp = bestCount;
            bestCount   = custInvoiceJour.RecId;
            bestAccount = custInvoiceJour.InvoiceAccount;
        }
        else if (custInvoiceJour.RecId > runnerUp)
        {
            runnerUp = custInvoiceJour.RecId;
        }
    }
    if (!bestAccount || bestCount == runnerUp)
    {
        return null;
    }

    return this.choiceQuestion('SALES', strFmt("Which customer received the most sales invoices in %1?", this.monthText(lastDate)),
        this.custText(bestAccount), this.customerNames(),
        strFmt("%1 received %2 invoices in %3.", this.custText(bestAccount), bestCount, this.monthText(lastDate)),
        'select count(RecId) from custInvoiceJour group by InvoiceAccount where custInvoiceJour.InvoiceDate >= monthStart && custInvoiceJour.InvoiceDate <= monthEnd;');
}

public DEVTutorialArcadeQuizQuestion qTopItemMonth()
{
    CustInvoiceTrans custInvoiceTrans;
    date             lastDate = this.lastInvoiceDate();
    ItemId           bestItem;
    real             bestQty;
    real             runnerUp;

    if (lastDate == dateNull())
    {
        return null;
    }

    while select sum(Qty) from custInvoiceTrans
        group by ItemId
        where custInvoiceTrans.InvoiceDate >= dateStartMth(lastDate)
           && custInvoiceTrans.InvoiceDate <= endMth(lastDate)
           && custInvoiceTrans.ItemId      != ''
    {
        if (custInvoiceTrans.Qty > bestQty)
        {
            runnerUp = bestQty;
            bestQty  = custInvoiceTrans.Qty;
            bestItem = custInvoiceTrans.ItemId;
        }
        else if (custInvoiceTrans.Qty > runnerUp)
        {
            runnerUp = custInvoiceTrans.Qty;
        }
    }
    if (!bestItem || bestQty == runnerUp)
    {
        return null;
    }

    return this.choiceQuestion('SALES', strFmt("Which item was sold the most (quantity) in %1?", this.monthText(lastDate)),
        this.itemText(bestItem), this.itemNames(),
        strFmt("%1 was invoiced %2 times in %3.", this.itemText(bestItem), DEVTutorialArcadeQuizEngine::formatNumber(bestQty), this.monthText(lastDate)),
        'select sum(Qty) from custInvoiceTrans group by ItemId where custInvoiceTrans.InvoiceDate >= monthStart && custInvoiceTrans.InvoiceDate <= monthEnd;');
}

