public DEVTutorialArcadeQuizQuestion qTopPayingCustomer()
{
    CustTrans     custTrans;
    date          lastDate;
    CustAccount   bestAccount;
    real          bestAmount;
    real          runnerUp;

    lastDate = this.lastPaymentDate();
    if (lastDate == dateNull())
    {
        return null;
    }

    while select sum(AmountMST) from custTrans
        group by AccountNum
        where custTrans.TransType == LedgerTransType::Payment
           && custTrans.TransDate >= dateStartMth(lastDate)
           && custTrans.TransDate <= endMth(lastDate)
    {
        if (abs(custTrans.AmountMST) > bestAmount)
        {
            runnerUp = bestAmount;
            bestAmount  = abs(custTrans.AmountMST);
            bestAccount = custTrans.AccountNum;
        }
        else if (abs(custTrans.AmountMST) > runnerUp)
        {
            runnerUp = abs(custTrans.AmountMST);
        }
    }
    if (!bestAccount || bestAmount == runnerUp)
    {
        return null;
    }

    return this.choiceQuestion('PAYMENTS', strFmt("Which customer paid the most in %1?", this.monthText(lastDate)),
        this.custText(bestAccount), this.customerNames(),
        strFmt("%1 paid %2 in %3.", this.custText(bestAccount), DEVTutorialArcadeQuizEngine::formatNumber(bestAmount), this.monthText(lastDate)),
        'select sum(AmountMST) from custTrans group by AccountNum where custTrans.TransType == LedgerTransType::Payment;');
}

