public DEVTutorialArcadeQuizQuestion qLastHired()
{
    HcmEmployment hcmEmployment, sameDay;
    str           workerName;

    select firstonly hcmEmployment
        order by ValidFrom desc;
    if (!hcmEmployment.RecId)
    {
        return null;
    }
    select count(RecId) from sameDay
        where sameDay.ValidFrom == hcmEmployment.ValidFrom;
    if (sameDay.RecId > 1)
    {
        return null;   // several workers started at the same moment
    }
    workerName = HcmWorker::find(hcmEmployment.Worker).name();

    return this.choiceQuestion('PEOPLE', "Who was hired most recently?", workerName, this.workerNames(),
        strFmt("%1 has the latest employment start date: %2.", workerName, DateTimeUtil::date(hcmEmployment.ValidFrom)),
        'select firstonly hcmEmployment order by ValidFrom desc;');
}

