public DEVTutorialArcadeQuizQuestion qNewestUser()
{
    UserInfo  userInfo;
    str       newest;
    container users;

    select firstonly userInfo
        order by RecId desc
        where userInfo.enable == 1;
    if (!userInfo.RecId)
    {
        return null;
    }
    newest = userInfo.id;

    while select id from userInfo
        where userInfo.enable == 1
    {
        users += userInfo.id;
        if (conLen(users) >= 60)
        {
            break;
        }
    }

    return this.choiceQuestion('SYSTEM', "Which user account was added most recently?", newest, users,
        strFmt("The newest enabled UserInfo record is \"%1\".", newest),
        'select firstonly userInfo order by RecId desc where userInfo.enable == 1;');
}

