/// <summary>
/// Gets the date of the latest sales invoice; the invoice questions use its month.
/// </summary>
private date lastInvoiceDate()
{
    CustInvoiceJour custInvoiceJour;
    date            monthStart;
    int             i;

    if (invoiceMonthCache == dateNull())
    {
        select maxof(InvoiceDate) from custInvoiceJour;
        monthStart = dateStartMth(custInvoiceJour.InvoiceDate);
        invoiceMonthCache = monthStart;

        // prefer the latest month with enough invoices, so the questions are meaningful
        for (i = 1; i <= 24 && monthStart > dateNull(); i++)
        {
            select count(RecId) from custInvoiceJour
                where custInvoiceJour.InvoiceDate >= monthStart
                   && custInvoiceJour.InvoiceDate <= endMth(monthStart);
            if (custInvoiceJour.RecId >= DEVTutorialArcadeQuizEngine::MinMonthRecords)
            {
                invoiceMonthCache = monthStart;
                break;
            }
            monthStart = dateStartMth(prevMth(monthStart));
        }
    }

    return invoiceMonthCache;
}

/// <summary>
/// Gets the latest month with at least MinMonthRecords customer payments.
/// </summary>
private date lastPaymentDate()
{
    CustTrans custTrans;
    date      monthStart;
    int       i;

    if (paymentMonthCache == dateNull())
    {
        select maxof(TransDate) from custTrans
            where custTrans.TransType == LedgerTransType::Payment;
        monthStart = dateStartMth(custTrans.TransDate);
        paymentMonthCache = monthStart;

        for (i = 1; i <= 24 && monthStart > dateNull(); i++)
        {
            select count(RecId) from custTrans
                where custTrans.TransType == LedgerTransType::Payment
                   && custTrans.TransDate >= monthStart
                   && custTrans.TransDate <= endMth(monthStart);
            if (custTrans.RecId >= DEVTutorialArcadeQuizEngine::MinMonthRecords)
            {
                paymentMonthCache = monthStart;
                break;
            }
            monthStart = dateStartMth(prevMth(monthStart));
        }
    }

    return paymentMonthCache;
}

/// <summary>
/// Gets the latest month with at least MinMonthRecords new sales orders.
/// </summary>
private date lastOrderMonth()
{
    SalesTable  salesTable;
    date        monthStart;
    utcdatetime fromDateTime, toDateTime;
    int         i;

    if (orderMonthCache == dateNull())
    {
        select maxof(CreatedDateTime) from salesTable;
        if (salesTable.CreatedDateTime == utcDateTimeNull())
        {
            return dateNull();
        }
        monthStart = dateStartMth(DateTimeUtil::date(salesTable.CreatedDateTime));
        orderMonthCache = monthStart;

        for (i = 1; i <= 24 && monthStart > dateNull(); i++)
        {
            fromDateTime = DateTimeUtil::newDateTime(monthStart, 0);
            toDateTime   = DateTimeUtil::newDateTime(endMth(monthStart), 86399);
            select count(RecId) from salesTable
                where salesTable.CreatedDateTime >= fromDateTime
                   && salesTable.CreatedDateTime <= toDateTime;
            if (salesTable.RecId >= DEVTutorialArcadeQuizEngine::MinMonthRecords)
            {
                orderMonthCache = monthStart;
                break;
            }
            monthStart = dateStartMth(prevMth(monthStart));
        }
    }

    return orderMonthCache;
}

private str monthText(date _date)
{
    return strFmt('%1 %2', mthName(mthOfYr(_date)), year(_date));
}

private str groupText(str _id, str _name)
{
    return _name ? strFmt('%1 - %2', _id, _name) : _id;
}

private str custText(CustAccount _accountNum)
{
    return strFmt('%1 %2', _accountNum, CustTable::find(_accountNum).name());
}

private str vendText(VendAccount _accountNum)
{
    return strFmt('%1 %2', _accountNum, VendTable::find(_accountNum).name());
}

private str itemText(ItemId _itemId)
{
    return strFmt('%1 %2', _itemId, InventTable::find(_itemId).defaultProductName());
}

/// <summary>
/// Gets customers to use as wrong answers.
/// </summary>
private container customerNames()
{
    CustTable custTable;

    if (!conLen(customerNameCache))
    {
        while select custTable
        {
            customerNameCache += strFmt('%1 %2', custTable.AccountNum, custTable.name());
            if (conLen(customerNameCache) >= 40)
            {
                break;
            }
        }
    }

    return customerNameCache;
}

private container vendorNames()
{
    VendTable vendTable;

    if (!conLen(vendorNameCache))
    {
        while select vendTable
        {
            vendorNameCache += strFmt('%1 %2', vendTable.AccountNum, vendTable.name());
            if (conLen(vendorNameCache) >= 40)
            {
                break;
            }
        }
    }

    return vendorNameCache;
}

private container itemNames()
{
    InventTable inventTable;

    if (!conLen(itemNameCache))
    {
        while select inventTable
        {
            itemNameCache += strFmt('%1 %2', inventTable.ItemId, inventTable.defaultProductName());
            if (conLen(itemNameCache) >= 40)
            {
                break;
            }
        }
    }

    return itemNameCache;
}

private container workerNames()
{
    HcmWorker hcmWorker;

    if (!conLen(workerNameCache))
    {
        while select hcmWorker
        {
            workerNameCache += hcmWorker.name();
            if (conLen(workerNameCache) >= 40)
            {
                break;
            }
        }
    }

    return workerNameCache;
}

/// <summary>
/// Formats a number without decimals and with thousands separators, e.g. 1,284,530.
/// </summary>
public static str formatNumber(real _value)
{
    return num2Str(round(_value, 1), 0, 0, 1, 2);
}

/// <summary>
/// Gets the rank shown at the end of the quiz.
/// </summary>
public static str title(int _percent)
{
    if (_percent >= 100)
    {
        return 'D365 WIZARD';
    }
    if (_percent >= 80)
    {
        return 'DATA GURU';
    }
    if (_percent >= 60)
    {
        return 'POWER USER';
    }
    if (_percent >= 40)
    {
        return 'KEY USER';
    }

    return 'NEW HIRE';
}

/// <summary>
/// Returns an error response; the quiz shows the message.
/// </summary>
public static str errorJson(str _message)
{
    return DEVTutorialArcadeJson::object([DEVTutorialArcadeJson::pair('error', DEVTutorialArcadeJson::quote(_message))]);
}

/// <summary>
/// Gets a random number from 1 to _max.
/// </summary>
public static int random(int _max)
{
    return _max > 1 ? (xGlobal::randomPositiveInt32() mod _max) + 1 : 1;
}

/// <summary>
/// Returns the values of a container in random order.
/// </summary>
public static container shuffle(container _values)
{
    container values = _values;
    anytype   value;
    int       i, j;

    for (i = conLen(values); i > 1; i--)
    {
        j     = DEVTutorialArcadeQuizEngine::random(i);
        value = conPeek(values, i);
        values = conPoke(values, i, conPeek(values, j));
        values = conPoke(values, j, value);
    }

    return values;
}

/// <summary>
/// Shuffles an array of objects in place.
/// </summary>
public static Array shuffleArray(Array _values)
{
    Object value;
    int    i, j;

    for (i = _values.lastIndex(); i > 1; i--)
    {
        j     = DEVTutorialArcadeQuizEngine::random(i);
        value = _values.value(i);
        _values.value(i, _values.value(j));
        _values.value(j, value);
    }

    return _values;
}
